import { cupLogo, type CupLogoColor, type CupLogoKind } from "@/lib/brand/cup";
import { cn } from "@/lib/utils";

interface CupLogoProps {
  kind?: CupLogoKind;
  color?: CupLogoColor;
  className?: string;
}

/** AUSDAUER CUP logo (outlined SVG files generated by scripts/generate-cup-logo.mts). */
export function CupLogo({ kind = "", color = "farbig", className }: CupLogoProps) {
  // eslint-disable-next-line @next/next/no-img-element -- static vector logo
  return <img src={cupLogo(kind, color)} alt="AUSDAUER CUP – Laufserie Siegerland" className={cn("h-10 w-auto", className)} />;
}

/** One dot per race; filled dots = races run. Used on certificates and the website season tracker. */
export function SeriesTrack({ total, done = [], className, light = false }: { total: number; done?: number[]; className?: string; light?: boolean }) {
  return (
    <ol className={cn("flex items-center", className)} aria-label={`${done.length} von ${total} Läufen absolviert`}>
      {Array.from({ length: total }, (_, i) => {
        const run = done.includes(i + 1);
        return (
          <li key={i} className="flex flex-1 items-center last:flex-none">
            <span
              className={cn(
                "flex size-6 shrink-0 items-center justify-center rounded-full border-2 font-mono text-[0.6rem] font-semibold tabular",
                light ? "border-paper" : "border-ink",
                run ? (light ? "bg-paper text-ink" : "bg-ink text-paper") : light ? "text-paper" : "text-ink",
              )}
            >
              {i + 1}
            </span>
            {i < total - 1 && <span aria-hidden className={cn("h-0.5 flex-1", light ? "bg-paper/60" : "bg-ink/60")} />}
          </li>
        );
      })}
    </ol>
  );
}
